-- V1.7 — question difficulty (additive; safe to run more than once).
-- Adds a nullable column and fills it ONLY where it is still NULL. Never deletes or rewrites questions.
alter table public.questions add column if not exists difficulty text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'questions_difficulty_check') then
    alter table public.questions add constraint questions_difficulty_check check (difficulty is null or difficulty in ('easy','medium','hard'));
  end if;
end $$;
create index if not exists questions_category_difficulty_idx on public.questions(category_id, difficulty);

update public.questions set difficulty = 'easy' where difficulty is null and id in ('fk-challenge-01', 'fk-challenge-02', 'fk-challenge-03', 'fk-challenge-05', 'fk-heritage-02', 'fk-password-02', 'fk-watani-01', 'fk-watani-02', 'fk-watani-06', 'nd96-complete-01', 'nd96-complete-07', 'nd96-complete-08', 'nd96-complete-10', 'nd96-complete-11', 'nd96-complete-12', 'nd96-emoji-01', 'nd96-emoji-03', 'nd96-emoji-08', 'nd96-emoji-13', 'nd96-password-01', 'nd96-password-03', 'nd96-password-05', 'nd96-password-06', 'nd96-password-07', 'nd96-password-08', 'nd96-password-12', 'nd96-password-13', 'nd96-saudi-07', 'nd96-saudi-10', 'nd96-saudi-11', 'nd96-saudi-13', 'nd96-speed-01', 'nd96-speed-02', 'nd96-speed-04', 'nd96-speed-05', 'nd96-speed-09', 'nd96-speed-12', 'nd96-speed-13', 'nd96-truefalse-02', 'nd96-truefalse-04', 'nd96-truefalse-06', 'nd96-truefalse-07', 'nd96-truefalse-09', 'nd96-truefalse-11', 'nd96-truefalse-12', 'nd96-watani-03', 'nd96-watani-04', 'nd96-watani-05', 'nd96-watani-09', 'nd96-watani-12', 'nd96-whois-01', 'nd96-whois-03', 'nd96-whois-06', 'nd96-whois-07', 'nd96-whois-09', 'nd96-whois-10');
